"""Persisted pending tool-confirmation payload.

Tracker-owned conversation state written by the tool-constraints runtime and
read by prompts and LLM schemas. Pause/resolve logic lives in
:mod:`rasa.mantle.orchestration.tool_execution.constraints`.
"""

from __future__ import annotations

from typing import Any, Dict, Optional

from pydantic import BaseModel, ConfigDict, Field

from rasa.mantle.tools.result import NextInstruction

# Event metadata tag for confirmation-resumed tool dispatches
# (``ToolExecuted.metadata``). Kept here next to the pending payload so
# tracker/prompt/schema layers share one confirmation-state module.
METADATA_TOOL_SOURCE_CONFIRMATION = "tool_confirmation"


class DeferredInstruction(BaseModel):
    """A ``ToolResult.next`` instruction held back until a confirmation resolves."""

    model_config = ConfigDict(frozen=True)

    tool_name: str
    instruction: NextInstruction


class PendingToolConfirmation(BaseModel):
    """Store a tool call waiting on an affirmative user reply.

    Persisted in ``system.pending_tool_confirmation`` so the next user turn can
    resume or cancel without relying on LLM tool-call replay.

    ``confirmation_ask`` is the rendered ask text shown to the user (response
    looked up and placeholders filled) when the builder set
    ``utter_for_confirmation``. ``utter_on_user_denial`` is the optional
    ``responses.yml`` response name stored at pause so decline can resolve it
    without a catalog lookup. Missing values leave the corresponding response
    to the LLM.
    """

    model_config = ConfigDict(frozen=True)

    tool_name: str
    tool_args: Dict[str, Any] = Field(default_factory=dict)
    confirmation_ask: Optional[str] = None
    utter_on_user_denial: Optional[str] = None
    skill_id: str
    frame_id: Optional[str] = None
    # When set, the pause came from an ordered-block ``execute_tool`` step. After
    # resolve (confirm or decline), the executor advances past that step so the
    # block does not re-enter the same gate.
    execute_step_id: Optional[str] = None
    # ``ToolResult.next`` instructions from other tools in the same LLM response.
    # Running them would move the frame this pause belongs to, so they wait and
    # are re-queued when the user confirms or declines.
    deferred_next: list[DeferredInstruction] = Field(default_factory=list)

    def is_owned_by(self, *, frame_id: Optional[str], skill_id: Optional[str]) -> bool:
        """Return whether the frame being removed is the one this pause belongs to.

        Ownership is the ``skill_id``, narrowed to ``frame_id`` when the pause
        recorded one. When the caller cannot name the skill, ``frame_id`` alone
        decides. Used when a stack edit drops frames so the pause does not
        outlive its owner.
        """
        if skill_id is None:
            return self.frame_id is not None and self.frame_id == frame_id
        if self.skill_id != skill_id:
            return False
        return self.frame_id is None or self.frame_id == frame_id
